const fs = require('fs');

const PREFS_FILE = '/home/node/.n8n/preferences.json';

function loadJSON(filePath, defaultData) {
  try {
    if (fs.existsSync(filePath)) {
      return JSON.parse(fs.readFileSync(filePath, 'utf8'));
    }
  } catch(e) {}
  return defaultData;
}

function saveJSON(filePath, data) {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2));
}

const userId = $input.first().json.query.userId;

if (!userId) {
  return [{ json: { status: 'error', message: 'Paramètre userId manquant' } }];
}

const data = loadJSON(PREFS_FILE, { preferences: [] });
const pref = data.preferences.find(p => p.userId === userId);

if (!pref) {
  return [{ json: { status: 'not_found', message: 'Utilisateur inconnu' } }];
}

pref.active = false;
saveJSON(PREFS_FILE, data);

return [{
  json: {
    status: 'unsubscribed',
    html: `<html><body style="font-family: Arial, sans-serif; text-align: center; padding: 50px;">
      <h1 style="color: #28a745;">✓ Désinscription réussie</h1>
      <p>Vous ne recevrez plus de newsletters Persona.</p>
      <p style="color: #6c757d; font-size: 12px;">Vous pouvez vous réabonner à tout moment depuis le chatbot.</p>
    </body></html>`
  }
}]
